package com.scriptles.cabinet.profile.entity;
import com.scriptles.cabinet.user.enums.FollowStatus; import jakarta.persistence.*; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="profile_follows",uniqueConstraints=@UniqueConstraint(name="uk_profile_follow",columnNames={"follower_profile_id","followed_profile_id"})) @Getter @Setter @NoArgsConstructor
public class ProfileFollow { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="follower_profile_id",nullable=false) private Profile follower; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="followed_profile_id",nullable=false) private Profile followed; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private FollowStatus status=FollowStatus.ACCEPTED; @Column(nullable=false) private Instant createdAt=Instant.now(); }
